const maxMessages = 500;
const pageSize = 100;
const requestDelayMs = 200;
const maxRetries = 3;
const retryBaseDelayMs = 1000;

if (!Number.isInteger(maxMessages) || maxMessages < 1 || maxMessages > 10000) {
  throw new Error('maxMessages must be an integer from 1 to 10000');
}
if (!Number.isInteger(pageSize) || pageSize < 1 || pageSize > 500) {
  throw new Error('pageSize must be an integer from 1 to 500');
}
if (!Number.isInteger(requestDelayMs) || requestDelayMs < 0 || requestDelayMs > 60000) {
  throw new Error('requestDelayMs must be an integer from 0 to 60000');
}
if (!Number.isInteger(maxRetries) || maxRetries < 0 || maxRetries > 10) {
  throw new Error('maxRetries must be an integer from 0 to 10');
}
if (!Number.isInteger(retryBaseDelayMs) || retryBaseDelayMs < 0 || retryBaseDelayMs > 60000) {
  throw new Error('retryBaseDelayMs must be an integer from 0 to 60000');
}

return [{
  json: {
    maxMessages,
    pageSize,
    requestDelayMs,
    maxRetries,
    retryBaseDelayMs,
    pagination: {
      nextPageToken: null,
      pagesFetched: 0,
      messagesDiscovered: 0,
      messageIds: []
    },
    apiRequests: 0,
    retryCount: 0,
    errors: []
  }
}];

const state = $('Configure Pagination').first().json;
const response = $input.first().json;
const pageSize = state.pageSize;
const maxMessages = state.maxMessages;

const messages = response.messages;
if (messages === undefined) {
  return [{
    json: {
      ...state,
      pagination: {
        ...state.pagination,
        pagesFetched: state.pagination.pagesFetched + 1,
        hasMorePages: false
      },
      apiRequests: state.apiRequests + 1
    }
  }];
}

if (!Array.isArray(messages)) {
  throw new Error('Unexpected Gmail messages list format');
}

if (messages.length > pageSize) {
  throw new Error('Gmail returned more messages than requested pageSize');
}

const ids = new Set(state.pagination.messageIds);
let newIds = [];
const currentCount = state.pagination.messageIds.length;

for (const message of messages) {
  if (typeof message.id !== 'string' || !/^[a-zA-Z0-9_-]+$/.test(message.id)) {
    throw new Error('Invalid Gmail message ID format');
  }
  if (!ids.has(message.id) && currentCount + newIds.length < maxMessages) {
    newIds.push(message.id);
    ids.add(message.id);
  }
}

const totalDiscovered = state.pagination.messagesDiscovered + messages.length;
const hasReachedLimit = (currentCount + newIds.length) >= maxMessages;
const nextPageToken = response.nextPageToken || null;
const hasMorePages = !hasReachedLimit && nextPageToken !== null && nextPageToken !== '';

return [{
  json: {
    ...state,
    pagination: {
      nextPageToken: nextPageToken,
      pagesFetched: state.pagination.pagesFetched + 1,
      messagesDiscovered: totalDiscovered,
      messageIds: [...state.pagination.messageIds, ...newIds],
      hasMorePages
    },
    apiRequests: state.apiRequests + 1
  }
}];

const delayMs = $('Configure Pagination').first().json.requestDelayMs;
if (typeof delayMs !== 'number' || delayMs < 0) {
  throw new Error('Invalid requestDelayMs');
}
await new Promise(resolve => setTimeout(resolve, delayMs));
return $input.all();

const config = $('Configure Pagination').first().json;
const state = $input.first().json;
const ids = state.pagination.messageIds;

if (!Array.isArray(ids) || ids.length === 0) {
  return [{
    json: {
      ...state,
      messagesAnalyzed: 0,
      unknownSenderCount: 0,
      senders: [],
      partial: ids.length === 0
    }
  }];
}

return ids.map(id => ({
  json: {
    id,
    state
  }
}));

const messages = $input.all();
const state = messages[0]?.json?.state;
if (!state) {
  throw new Error('Missing pagination state');
}

const groups = new Map();
const processedIds = new Set();
let unknownSenderCount = 0;
let successCount = 0;
let errorCount = 0;

for (const item of messages) {
  const message = item.json;
  const messageId = message.id;

  if (!messageId || typeof messageId !== 'string') {
    errorCount++;
    continue;
  }

  if (processedIds.has(messageId)) {
    continue;
  }
  processedIds.add(messageId);
  successCount++;

  if (!Array.isArray(message.payload?.headers)) {
    unknownSenderCount++;
    continue;
  }

  const headers = message.payload.headers;
  if (headers.some((header) => !header || typeof header.name !== 'string' || typeof header.value !== 'string')) {
    unknownSenderCount++;
    continue;
  }

  const values = (name) => headers.filter((header) => header.name.toLowerCase() === name).map((header) => header.value);
  const from = values('from');
  const raw = from.length === 1 ? from[0].trim() : '';

  const angle = raw.match(/^([^<>@]*)<([^<>]+)>\s*$/);
  const address = (angle ? angle[2] : raw).trim().toLowerCase();
  const parts = address.split('@');
  const local = parts[0];
  const domain = parts[1];

  const atom = "[a-z0-9!#$%&'*+\\/?^_`{|}~-]+";
  const validLocal = new RegExp('^' + atom + '(?:\\.' + atom + ')*$').test(local);
  const validDomain = domain && domain.split('.').every((label) => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(label));

  if (parts.length !== 2 || !validLocal || !validDomain || local.length > 64 || domain.length > 253) {
    unknownSenderCount++;
    continue;
  }

  if (!groups.has(address)) {
    groups.set(address, {
      sender: address,
      count: 0,
      signals: { listUnsubscribe: 0, bulkOrListPrecedence: 0, noReplyAddress: 0 }
    });
  }

  const group = groups.get(address);
  group.count++;

  if (values('list-unsubscribe').some((value) => value.trim() !== '')) {
    group.signals.listUnsubscribe++;
  }
  if (values('precedence').some((value) => /^(bulk|list|junk)$/i.test(value.trim()))) {
    group.signals.bulkOrListPrecedence++;
  }
  if (/^(no[-_.]?reply|do[-_.]?not[-_.]?reply|notifications?)$/.test(local)) {
    group.signals.noReplyAddress++;
  }
}

const senders = [...groups.values()]
  .map((group) => ({
    ...group,
    category: Object.values(group.signals).some((count) => count > 0) ? 'potential_newsletter_or_automated' : 'no_signal',
    safeToDelete: false
  }))
  .sort((a, b) => b.count - a.count || a.sender.localeCompare(b.sender));

return [{
  json: {
    ...state,
    messagesAnalyzed: successCount,
    unknownSenderCount,
    uniqueSenderCount: groups.size,
    senders,
    partial: successCount < state.pagination.messageIds.length
  }
}];
